code.common:
float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

float fbm(float2 p)
{
    float v = 0.0;
    float a = 0.5;
    for (int k = 0; k < 4; k++) { v += a * vnoise(p); p = p * 2.03 + float2(1.7, 9.2); a *= 0.5; }
    return v;
}

// x: yarıçap (R0 0.94 = uç yolu), y: yay boyunca 0 kuyruk (165°) → 1 baş (15°)
float2 arcRS(float2 uv)
{
    float2 p = uv - 0.5;
    float r = length(p) * 2.0;
    float th = atan2(p.y, p.x) * 57.29578;
    th = th + step(th, -90.0) * 360.0;
    return float2(r, (165.0 - th) / 150.0);
}

// hilal kalınlık profili: kuyrukta sivri, başa yakın kalın, başta hızla incelir
float arcProfile(float sc)
{
    return pow(sc, 0.9) * (1.0 - smoothstep(0.86, 1.0, sc));
}

code.fragment:
float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float2 a = arcRS(i.uv);
    float r = a.x;
    float s = a.y;
    float sc = saturate(s);
    float inArc = step(0.0, s) * step(s, 1.0);
    float R0 = 0.94;

    float w = _Width * arcProfile(sc);
    // lifler: kılıç yolu boyunca uzayan çizgiler (yarıçapta hızlı, yayda yavaş değişir)
    float st = fbm(float2(r * _Fiber, sc * 2.5));
    float st2 = vnoise(float2(r * _Fiber * 2.7 + 5.0, sc * 7.0));
    float fib = saturate(st * 0.7 + st2 * 0.5);
    float clump = vnoise(float2(sc * 8.0, 2.0));
    float innerR = R0 - w * (0.75 + (st - 0.5) * 0.9 + (clump - 0.5) * 0.4);
    float band = smoothstep(innerR - 0.004, innerR + 0.025, r) * (1.0 - smoothstep(R0 - 0.004, R0 + 0.004, r));
    float d = saturate((r - innerR) / max(R0 - innerR, 0.001));

    float rev = saturate(life / _Reveal);
    float revealM = 1.0 - smoothstep(rev * 1.04 - 0.05, rev * 1.04, s);
    float e = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));
    float er = fbm(float2(s * 7.0, r * 9.0));
    float erodeM = saturate((er + 0.5 - e * 1.35 - (1.0 - sc) * e * 0.6) * 6.0);

    float3 col = lerp(_Navy.rgb, _Mid.rgb, saturate(d * 1.4));
    col = lerp(col, _Hi.rgb, pow(saturate(d * 1.2 - 0.2), 2.2));
    col *= 0.35 + 1.15 * fib;
    col *= i.color.rgb;
    float op = band * inArc * revealM * erodeM * (0.4 + 0.6 * d) * (0.3 + 0.7 * fib) * _Opacity;
    return float4(col, saturate(op));
}
